dition_target":"presence","duration_in_world_hours":null},{"effect_kind":"trigger_event","trigger_event_kind":"bell_court_proximity_detection_30ft","duration_in_world_hours":null}],"weight_lb":0.05,"value_cp":1200,"weapon_properties":[],"witness_payload":{"soul_kind":"bound","soul_source_event_id":"event_charm_attuned_during_salt_vigil","soul_intensity":4,"provenance_chain":[{"holder_id":"fac_civic_bell_court_treasury","held_from_day":-200,"held_until_day":-45,"transfer_kind":"gifted","transfer_event_id":"event_charm_minted_for_civic_ceremony"}]},"tags":["slice_eligible","faction_aligned_bell_court","witness_bearing","attunement_required","v0_9_crafting_graph_pending","v0_9_on_use_effect_pending"]},{"item_id":"item_marrow_wax_seal_of_ilyra","name":"Marrow-Wax Seal of Ilyra","type":"wondrous","rarity":"very_rare","regional_pack_id":"greywake","description_short":"A small wax seal — drowned-red wax over an iron core — bearing the personal sigil of Marrow-Saint Ilyra. Cannot be melted by ordinary fire.","description_long":"A finger-sized seal of marrow-wax pressed into an iron core. The drowned-red wax bears Marrow-Saint Ilyra''s personal sigil — a salt-ring around a vertical line. Cool to the touch even when held over flame; the marrow does not render unless the holder is rendering the marrow''s source. Sworn (not attuned): the bond is permanent and broken only by the seal''s destruction or by death.","magical":true,"requires_attunement":true,"attunement_ceremony":"sworn_oath","attunement_slot_cost":1,"effects_on_attune_structured":[{"effect_kind":"stat_modifier","magnitude_int":2,"condition_target":"will","duration_in_world_hours":null},{"effect_kind":"condition_apply","condition_target":"bonded_to_marrow_saint_ilyra","magnitude_int":null,"duration_in_world_hours":null},{"effect_kind":"save_advantage","condition_target":"saves_against_drowned_red_conditions","magnitude_int":null}],"effects_on_use_structured":[{"effect_kind":"trigger_event","trigger_event_kind":"call_marrow_saint_to_current_scene","charges_per_use":1}],"charges_max":1,"charges_recover":"never_until_resworn","weight_lb":0.1,"value_cp":0,"value_note":"not for sale; sworn-gift only","weapon_properties":[],"witness_payload":{"soul_kind":"fragment","soul_source_event_id":"event_ilyra_personal_oath","soul_intensity":8,"provenance_chain":[{"holder_id":"npc_marrow_saint_ilyra","held_from_day":-1200,"held_until_day":null,"transfer_kind":"gifted","transfer_event_id":null}]},"tags":["slice_eligible","faction_aligned_drowned_church","witness_bearing","sworn","bonds_to_npc","deicidal_potential_post_slice"]},{"item_id":"item_listening_childs_pebble","name":"The Listening Child''s Pebble","type":"trinket","rarity":"legendary","regional_pack_id":"greywake","description_short":"A small smooth pebble. Warm. Cannot be lost.","description_long":"An almost-perfectly-round pebble the size of a fingernail. The Listening Child gave it to you. It is warm in your pocket. It does not chip. It does not weather. If you set it down it is back in your pocket within a scene; if you drop it intentionally it is back within a turn. There is no inscription on it. There is no sound when you hold it to your ear.","magical":true,"requires_attunement":false,"attunement_ceremony":null,"attunement_slot_cost":0,"effects_passive_structured":[{"effect_kind":"trigger_event","trigger_event_kind":"auto_return_to_player_inventory_on_drop_or_loss"},{"effect_kind":"trigger_event","trigger_event_kind":"creation_stat_increment_threshold_witness","magnitude_int":1}],"effects_on_use_structured":[{"effect_kind":"trigger_event","trigger_event_kind":"pose_question_to_the_listening_child_remotely","charges_per_use":1}],"charges_max":1,"charges_recover":"long_rest_anywhere","weight_lb":0.01,"value_cp":0,"value_note":"not for sale; ungiftable; canon-event-only acquisition","weapon_properties":[],"witness_payload":{"soul_kind":"echo","soul_source_event_id":"event_practicing_water_spoken_at_fountain","soul_intensity":10,"provenance_chain":[{"holder_id":"npc_the_listening_child","held_from_day":null,"held_until_day":null,"transfer_kind":"gifted","transfer_event_id":"event_listening_child_gifts_pebble"}]},"acquisition_method":"canon_event_only","tags":["slice_eligible","canon_event_acquired","witness_bearing","unloseable","legendary"]},{"item_id":"item_vial_of_practiced_name_water","name":"Vial of Practiced-Name Water","type":"consumable","rarity":"rare","regional_pack_id":"greywake","description_short":"A small glass vial holding clear water that hums faintly when held close to the ear.","description_long":"A finger-length vial of clear water gathered at the dry fountain during a successful Hear-the-Fountain casting. The water is practicing — there is no clearer term — and the practice is audible at very close range. Drink to gain temporary fluency in unspoken names; pour onto an object to allow Compose to target that object regardless of distance.","magical":true,"requires_attunement":false,"attunement_slot_cost":0,"effects_on_use_structured":[{"effect_kind":"condition_apply","condition_target":"practicing_water_drunk","magnitude_int":1,"duration_in_world_hours":1},{"effect_kind":"trigger_event","trigger_event_kind":"enable_remote_compose_target"}],"charges_max":1,"charges_recover":"never_consumable","weight_lb":0.05,"value_cp":350,"value_note":"tradeable; Drowned Church will pay premium","weapon_properties":[],"witness_payload":null,"is_intermediate":true,"intermediate_for_recipe_ids":["recipe_bell_marked_charm","recipe_marrow_wax_seal_replica"],"tags":["slice_eligible","intermediate","consumable","ritual_ingredient"]},{"item_id":"item_salt_rime_shard","name":"Salt-Rime Shard","type":"consumable","rarity":"uncommon","regional_pack_id":"greywake","description_short":"A small angular crystal of salt-rime, gathered from the dry fountain or any Greywake surface where the rime has accreted.","description_long":"Salt that has formed in defiance of weather. Brittle, sharp at the edges, oddly warm in the hand. Used in salt-immersion ceremonies, in Salt-Mark casting, and as a binding agent in marrow-wax preparation. Decays outside Greywake — crumbles to ordinary salt within three turns of leaving the region.","magical":true,"requires_attunement":false,"attunement_slot_cost":0,"effects_on_use_structured":[{"effect_kind":"trigger_event","trigger_event_kind":"fuel_salt_immersion_ceremony"},{"effect_kind":"trigger_event","trigger_event_kind":"fuel_salt_mark_spell_cast"}],"charges_max":1,"charges_recover":"never_consumable","weight_lb":0.02,"value_cp":60,"weapon_properties":[],"witness_payload":null,"decay_states":[{"decay_kind":"region_locked","decay_trigger":"leaves_region_greywake","decay_outcome":"becomes_ordinary_salt_within_3_turns"}],"tags":["slice_eligible","consumable","ritual_ingredient","region_locked"]},{"item_id":"item_witness_bell","name":"Witness Bell","type":"tool","rarity":"rare","regional_pack_id":"greywake","description_short":"A small handbell of brass-and-bone. Rings only in the presence of a witnessed canon event within thirty paces.","description_long":"A handbell of mottled brass and a single curved sliver of bone for the clapper. Silent in transit. Rings — sharp, brief, unignorable — whenever a canon-progression event is committed within thirty paces of the bearer. The bell cannot be silenced and cannot be moved while ringing; it will ring in the bearer''s pocket until released.","magical":true,"requires_attunement":true,"attunement_ceremony":"short_rest","attunement_slot_cost":1,"effects_on_attune_structured":[{"effect_kind":"trigger_event","trigger_event_kind":"announce_canon_event_within_30ft"},{"effect_kind":"stat_modifier","magnitude_int":1,"condition_target":"sense"}],"charges_max":null,"charges_recover":null,"weight_lb":0.5,"value_cp":900,"weapon_properties":[],"witness_payload":{"soul_kind":"echo","soul_intensity":5},"tags":["slice_eligible","investigative_tool","witness_bearing","attunement_required"]},{"item_id":"item_drowned_amber_pendant","name":"Drowned-Amber Pendant","type":"wondrous","rarity":"uncommon","regional_pack_id":"greywake","description_short":"A pendant of drowned-amber on a wet leather cord. The amber holds something small that does not decompose.","description_long":"A walnut-sized piece of drowned-amber strung on a salt-stained leather cord. The amber holds a single small thing — a fingerbone, an inscribed coin, a flake of paper — that has been inside the amber long enough that the thing has stopped trying to be itself. Worn by Drowned Church initiates; signals doctrinal allegiance.","magical":true,"requires_attunement":false,"attunement_slot_cost":0,"effects_passive_structured":[{"effect_kind":"stat_modifier","magnitude_int":1,"condition_target":"faith_drowned_church_visible_to_observers"}],"weight_lb":0.1,"value_cp":240,"weapon_properties":[],"witness_payload":{"soul_kind":"fragment","soul_intensity":2},"tags":["slice_eligible","faction_aligned_drowned_church","social_signal","witness_bearing"]},{"item_id":"item_tide_league_scrip_bundle_25","name":"Tide League Scrip Bundle (25)","type":"currency_token","rarity":"common","regional_pack_id":"greywake","description_short":"A tied bundle of 25 salt-scrip notes — Tide League issue, redeemable in tide-cycles.","description_long":"A canvas-tied bundle of 25 salt-scrip notes. Each note is a small rectangle of salt-fixed parchment stamped with the Tide League weighing-pan sigil. Redeemable at Tide League offices for goods at face value, or tradeable to other factions at exchange rates that vary by tide-cycle.","magical":false,"requires_attunement":false,"attunement_slot_cost":0,"weight_lb":0.2,"value_cp":250,"value_in_scrip":25,"weapon_properties":[],"stackable":true,"stack_size_max":999,"tags":["slice_eligible","currency","tide_league_issued"]},{"item_id":"item_bell_court_inkwell_stamp","name":"Bell Court Inkwell-Stamp","type":"tool","rarity":"uncommon","regional_pack_id":"greywake","description_short":"A small brass inkwell fitted with a stamp head. Bell Court issue. Stamps a canon-mark on parchment that the Court will recognize.","description_long":"A finger-sized brass inkwell with a hinged stamp head. The stamp leaves a small canon-mark on parchment — a circle around a vertical bar — that the Bell Court treats as an authorized minor witness mark. Issued by the Bell Court to junior clerks; can be acquired through quest, theft, or purchase from a Bell Court informant.","magical":false,"requires_attunement":false,"attunement_slot_cost":0,"effects_on_use_structured":[{"effect_kind":"trigger_event","trigger_event_kind":"issue_bell_court_minor_witness_mark","charges_per_use":1}],"charges_max":25,"charges_recover":"refill_at_bell_court_precinct","weight_lb":0.3,"value_cp":180,"weapon_properties":[],"tags":["slice_eligible","faction_aligned_bell_court","tool"]},{"item_id":"item_meteoric_iron_dagger","name":"Meteoric Iron Dagger","type":"weapon","rarity":"rare","regional_pack_id":"greywake","description_short":"A short dagger of meteoric iron, hammered cold. Cuts through wards.","description_long":"A thin double-edged dagger forged from meteoric iron — the metal still slightly warm to the touch from the cold-hammering. Ward-cutting: bypasses contradiction wards and salt-circle wards at the cost of a Ruin +1 to the wielder per use. Greywake-forged; one of three known to exist in the region.","magical":true,"requires_attunement":true,"attunement_ceremony":"blood_consecration","attunement_slot_cost":1,"effects_on_attune_structured":[{"effect_kind":"damage_resist","condition_target":"psychic_warding_resistance"}],"effects_on_use_structured":[{"effect_kind":"trigger_event","trigger_event_kind":"bypass_contradiction_or_salt_ward","magnitude_int":1},{"effect_kind":"meter_delta","condition_target":"ruin","magnitude_int":1,"duration_in_world_hours":null}],"damage_dice":"1d4+1","damage_type":"piercing","weight_lb":0.5,"value_cp":1800,"weapon_properties":["finesse","light","thrown","witness_marked"],"witness_payload":{"soul_kind":"fragment","soul_intensity":3},"tags":["slice_eligible","weapon","ward_cutter","ruin_inducing","attunement_required"]},{"item_id":"item_compose_chalk","name":"Compose-Chalk","type":"consumable","rarity":"uncommon","regional_pack_id":"greywake","description_short":"A short stick of compressed marrow-and-salt chalk. Drawn lines hold a Compose target for the rite''s duration.","description_long":"A stub of dense pale chalk — pressed marrow, fine salt, and a binding agent the Drowned Church does not disclose. Drawn lines hold their shape under rain and are visible to Drowned Church members regardless of distance. Used to mark the boundary of a Compose ritual; one stick supports one ritual.","magical":true,"requires_attunement":false,"effects_on_use_structured":[{"effect_kind":"trigger_event","trigger_event_kind":"establish_compose_ritual_boundary","charges_per_use":1}],"charges_max":1,"charges_recover":"never_consumable","weight_lb":0.1,"value_cp":120,"weapon_properties":[],"tags":["slice_eligible","consumable","ritual_ingredient","faction_aligned_drowned_church"]},{"item_id":"item_field_journal_blank","name":"Field Journal (blank)","type":"book","rarity":"common","regional_pack_id":"greywake","description_short":"A salt-stained leather field journal with 80 blank pages. Writes player-authored entries into the Tale Log.","description_long":"An ordinary field journal — leather cover, ribbon bookmark, 80 numbered blank pages. Writing in the journal at end-of-scene commits the entry to the player''s Tale Log, with the journal voice (Caveat font, brass margin marks). Used by all three factions as a discreet record; not factional itself.","magical":false,"requires_attunement":false,"effects_on_use_structured":[{"effect_kind":"trigger_event","trigger_event_kind":"commit_tale_log_entry_from_player_input"}],"charges_max":80,"charges_recover":"page_consumed_per_entry","weight_lb":0.8,"value_cp":90,"weapon_properties":[],"tags":["slice_eligible","narrative_tool","neutral"]}]'::jsonb) AS x
ON CONFLICT ("item_id") DO NOTHING;

